class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class StreamChecker:
    def __init__(self, words):
        self.root = TrieNode()
        self.stream = []
        for w in words:
            node = self.root
            for c in reversed(w):                          # insert word REVERSED
                node = node.children.setdefault(c, TrieNode())
            node.is_end = True

    def query(self, letter):
        self.stream.append(letter)
        node = self.root
        for c in reversed(self.stream):                     # walk BACKWARD from the newest character
            if c not in node.children:
                return False
            node = node.children[c]
            if node.is_end:
                return True
        return False

