import java.util.*;

class TrieNode {
    Map<Character, TrieNode> children = new HashMap<>();
    boolean isEnd = false;
}

class StreamChecker {
    TrieNode root = new TrieNode();
    List<Character> stream = new ArrayList<>();

    StreamChecker(String[] words) {
        for (String w : words) {
            TrieNode node = root;
            for (int i = w.length() - 1; i >= 0; i--) {          // insert word REVERSED
                char c = w.charAt(i);
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            }
            node.isEnd = true;
        }
    }

    boolean query(char letter) {
        stream.add(letter);
        TrieNode node = root;
        for (int i = stream.size() - 1; i >= 0; i--) {          // walk BACKWARD from the newest character
            char c = stream.get(i);
            if (!node.children.containsKey(c)) return false;
            node = node.children.get(c);
            if (node.isEnd) return true;
        }
        return false;
    }
}

