#include <bits/stdc++.h>
using namespace std;

struct TrieNode { unordered_map<char, TrieNode*> children; bool isEnd = false; };

class StreamChecker {
public:
    TrieNode* root = new TrieNode();
    vector<char> stream;

    StreamChecker(vector<string>& words) {
        for (auto& w : words) {
            TrieNode* node = root;
            for (int i = (int)w.size() - 1; i >= 0; i--) {        // insert word REVERSED
                char c = w[i];
                if (!node->children.count(c)) node->children[c] = new TrieNode();
                node = node->children[c];
            }
            node->isEnd = true;
        }
    }

    bool query(char letter) {
        stream.push_back(letter);
        TrieNode* node = root;
        for (int i = (int)stream.size() - 1; i >= 0; i--) {       // walk BACKWARD from the newest character
            char c = stream[i];
            if (!node->children.count(c)) return false;
            node = node->children[c];
            if (node->isEnd) return true;
        }
        return false;
    }
};
